UPDATE editorial_documents SET document = '{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Leo RD is a Dominican record producer and one of the central figures in dembow. Born Leonardo Felipe Yasmil Garcés in Los Guandules, Santo Domingo, on 28 March 1985, he built his first studio in a bathroom and has since produced a large share of the genre’s hits, among them «Linda», the 2021 record by ","type":"text"},{"type":"artistReference","attrs":{"artistId":"3e1718be-c12d-42f5-85e7-2156d9574940","displayText":"Tokischa","occurrenceId":"915bda3e-89cf-4a35-8437-23bcfa8c4ea8"}},{"text":" and Rosalía. He is signed to «Roc Nation» and still keeps his studio in the neighbourhood where he grew up.","type":"text"}]},{"type":"paragraph","content":[{"text":"Los Guandules","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Garcés came to music at nineteen. His first recording room was a bathroom in Los Guandules, soundproofed with egg cartons. For years he worked as an orderly at a gynaecology and obstetrics clinic and recorded around the shift — out of the studio at six in the morning, at the clinic by eight. He charged five hundred or a thousand pesos a session, and often nothing at all, because the artists he was recording had no money either. His first hit was «991», with J Fran; it took over the street and earned nothing.","type":"text"}]},{"type":"paragraph","content":[{"text":"The room in the neighbourhood","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"The turn came when the records began to hold. «Dejen su loquera», «La gallina», «Curuleca» and «La pámpara» kept him on the street continuously, and when he counted more than ten songs charting at once he left the clinic. Most of dembow’s names passed through the Los Guandules room on the way up, among them ","type":"text"},{"type":"artistReference","attrs":{"artistId":"71ebd02b-8ba4-4cd7-b7e4-a990a9c3c3bb","displayText":"Rochy RD","occurrenceId":"c424c90c-6e84-4f63-a160-008c6597c12f"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"518354a4-7cb9-4c39-a2b8-9fa4d18f50db","displayText":"El Mayor Clásico","occurrenceId":"93332a16-fb12-41af-916c-06146634ccdb"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"9be0ed08-6eb6-4ca0-bb68-d5126190aeb1","displayText":"Kiko el Crazy","occurrenceId":"fbae6ff8-68ad-4a71-a11e-db32d3847ac9"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"cf438c62-e0b8-4ba9-8e4b-f328ddce0c9b","displayText":"Chimbala","occurrenceId":"92ce1c72-6811-4915-92d5-3b2f6819ec70"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"bb07dcb8-444f-4a68-a668-21e9e038f335","displayText":"Yomel el Meloso","occurrenceId":"f003cb21-1b24-4652-98d3-5183b3ea668e"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"0b2e1a39-b265-42d6-95d5-85ad930eee84","displayText":"El Cherry Scom","occurrenceId":"28bff8e0-ec6d-4d58-ab49-6d67f7d8c738"}},{"text":", ","type":"text"},{"type":"artistReference","attrs":{"artistId":"2993cde1-f93d-4cf0-9668-fa1e54b09919","displayText":"Haraca Kiko","occurrenceId":"76cd0a96-df91-4f2e-a437-9ff7a35fce62"}},{"text":" and ","type":"text"},{"type":"artistReference","attrs":{"artistId":"95e181f1-58e5-4537-a5e8-75a9f60c6aca","displayText":"Tivi Gunz","occurrenceId":"e6dfceae-929f-4fc0-b967-cefbe0224b8f"}},{"text":". He has kept the studio there rather than move it.","type":"text"}]},{"type":"paragraph","content":[{"text":"«Linda»","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"In October 2020 he produced «Desacato Escolar» for Tokischa and Yomel el Meloso; YouTube pulled it over the lyrics, which sent people looking for it. The following year he produced «Linda», Tokischa’s record with Rosalía, shot in Santo Domingo and performed at the «Billboard Latin Music Awards» that September. He has since worked with J Balvin, Ozuna, Anuel AA, Myke Towers, De La Ghetto and Jowell y Randy, and his credits include «Corre Corre», «Alta Gama», «Pikilao», «La Cuarentena», «Rumba» and «La Máxima».","type":"text"}]},{"type":"paragraph","content":[{"text":"Legacy","type":"text","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"text":"Leo RD is among the producers who gave dembow the sound it now exports. He works by preference with new artists, which is why a large part of the genre’s roster made its first recordings in a room in Los Guandules rather than in a commercial studio.","type":"text"}]}]}'::jsonb, revision = revision + 1, updated_at = now() WHERE id = (SELECT d.id FROM editorial_documents d JOIN artists a ON a.id = d.owner_artist_id WHERE a.slug = 'leo-rd' AND d.locale = 'en' AND d.document_type = 'artist_biography');
UPDATE artists SET bio_en = 'Leo RD is a Dominican record producer and one of the central figures in dembow. Born Leonardo Felipe Yasmil Garcés in Los Guandules, Santo Domingo, on 28 March 1985, he built his first studio in a bathroom and has since produced a large share of the genre’s hits, among them «Linda», the 2021 record by Tokischa and Rosalía. He is signed to «Roc Nation» and still keeps his studio in the neighbourhood where he grew up.

**Los Guandules**

Garcés came to music at nineteen. His first recording room was a bathroom in Los Guandules, soundproofed with egg cartons. For years he worked as an orderly at a gynaecology and obstetrics clinic and recorded around the shift — out of the studio at six in the morning, at the clinic by eight. He charged five hundred or a thousand pesos a session, and often nothing at all, because the artists he was recording had no money either. His first hit was «991», with J Fran; it took over the street and earned nothing.

**The room in the neighbourhood**

The turn came when the records began to hold. «Dejen su loquera», «La gallina», «Curuleca» and «La pámpara» kept him on the street continuously, and when he counted more than ten songs charting at once he left the clinic. Most of dembow’s names passed through the Los Guandules room on the way up, among them Rochy RD, El Mayor Clásico, Kiko el Crazy, Chimbala, Yomel el Meloso, El Cherry Scom, Haraca Kiko and Tivi Gunz. He has kept the studio there rather than move it.

**«Linda»**

In October 2020 he produced «Desacato Escolar» for Tokischa and Yomel el Meloso; YouTube pulled it over the lyrics, which sent people looking for it. The following year he produced «Linda», Tokischa’s record with Rosalía, shot in Santo Domingo and performed at the «Billboard Latin Music Awards» that September. He has since worked with J Balvin, Ozuna, Anuel AA, Myke Towers, De La Ghetto and Jowell y Randy, and his credits include «Corre Corre», «Alta Gama», «Pikilao», «La Cuarentena», «Rumba» and «La Máxima».

**Legacy**

Leo RD is among the producers who gave dembow the sound it now exports. He works by preference with new artists, which is why a large part of the genre’s roster made its first recordings in a room in Los Guandules rather than in a commercial studio.' WHERE slug = 'leo-rd';
